namespace sv_29cdf525157249dcbc0911fdd6ec9937.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service — one instance per circuit (per user).
/// Holds theme state and notifies subscribers on change.
/// </summary>
public class ThemeService
{
    private ThemeMode _theme = ThemeMode.System;
    private string _accentColor = "#0078d4";

    public ThemeMode Theme
    {
        get => _theme;
        set
        {
            if (_theme == value) return;
            _theme = value;
            NotifyChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyChanged();
        }
    }

    public event Action? OnChange;

    private void NotifyChanged() => OnChange?.Invoke();
}

@using sv_29cdf525157249dcbc0911fdd6ec9937.Services
@inject ThemeService ThemeSvc
@implements IDisposable

<span class="theme-indicator" style="color: @ThemeSvc.AccentColor;" title="Current theme">
    @GetIcon() @ThemeSvc.Theme
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeSvc.OnChange += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private string GetIcon() => ThemeSvc.Theme switch
    {
        ThemeMode.Light => "☀️",
        ThemeMode.Dark => "🌙",
        _ => "💻"
    };

    public void Dispose()
    {
        ThemeSvc.OnChange -= HandleThemeChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@using sv_29cdf525157249dcbc0911fdd6ec9937.Services
@inject ThemeService ThemeSvc
@implements IDisposable

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="settings-panel">
    <div class="setting-group">
        <label>Theme</label>
        <select @bind="SelectedTheme">
            @foreach (var mode in Enum.GetValues<ThemeMode>())
            {
                <option value="@mode">@mode</option>
            }
        </select>
    </div>

    <div class="setting-group">
        <label>Accent Color</label>
        <input type="color" @bind="AccentColor" />
        <span style="color: @AccentColor;">Sample text</span>
    </div>
</div>

@code {
    private ThemeMode SelectedTheme
    {
        get => ThemeSvc.Theme;
        set => ThemeSvc.Theme = value;
    }

    private string AccentColor
    {
        get => ThemeSvc.AccentColor;
        set => ThemeSvc.AccentColor = value;
    }

    protected override void OnInitialized()
    {
        ThemeSvc.OnChange += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeSvc.OnChange -= HandleThemeChanged;
    }
}

